const weatherStatus=document.getElementById("weather-status"),weatherDetails=document.getElementById("weather-details"),CACHE_KEY="lakeLouiseWeather",CACHE_DURATION=600*1e3;async function loadWeather(){const t="https://api.open-meteo.com/v1/forecast?latitude=51.4167&longitude=-116.2167&current=temperature_2m,wind_speed_10m";try{const e=JSON.parse(sessionStorage.getItem(CACHE_KEY));if(e&&Date.now()-e.savedAt<CACHE_DURATION&&Number.isFinite(e.temperature)&&Number.isFinite(e.wind)){weatherStatus.textContent="Recent estimated conditions (cached):",weatherDetails.textContent=`Temperature: ${e.temperature} \xB0C | Wind: ${e.wind} km/h`;return}}catch(e){console.warn("Weather cache unavailable:",e)}const a=new AbortController,i=setTimeout(()=>a.abort(),8e3);try{const e=await fetch(t,{signal:a.signal});if(!e.ok)throw new Error("Weather API request failed.");const o=await e.json(),n=o.current?.wind_speed_10m,r=o.current?.temperature_2m;if(!Number.isFinite(r)||!Number.isFinite(n))throw new Error("Invalid weather data.");weatherStatus.textContent="Current estimated conditions:",weatherDetails.textContent=`Temperature: ${r} \xB0C | Wind: ${n} km/h`;try{sessionStorage.setItem(CACHE_KEY,JSON.stringify({temperature:r,wind:n,savedAt:Date.now()}))}catch(s){console.warn("Could not save weather cache:",s)}}catch(e){weatherStatus.textContent="Weather information is currently unavailable.",weatherDetails.textContent="",console.error("Weather error:",e)}finally{clearTimeout(i)}}loadWeather();const mapButton=document.getElementById("load-map"),mapContainer=document.getElementById("map-container"),mapNotice=document.getElementById("map-notice");mapButton.addEventListener("click",function(){const t=document.createElement("iframe");t.title="OpenStreetMap showing Lake Louise, Alberta",t.src="https://www.openstreetmap.org/export/embed.html?bbox=-116.22%2C51.40%2C-116.14%2C51.43&layer=mapnik",t.loading="lazy",t.referrerPolicy="strict-origin-when-cross-origin",t.setAttribute("sandbox","allow-scripts allow-same-origin"),mapContainer.appendChild(t),mapContainer.hidden=!1,mapButton.hidden=!0,mapNotice.textContent="Map requested from OpenStreetMap. Third-party requests may occur."});
